import { PrismaClient } from "@prisma/client";

// Where data lives:
//   - DATABASE_URL=postgres://…  → Postgres (e.g. Neon or Vercel Postgres); client generated by scripts/db-setup.mjs
//   - DATABASE_URL=file:…        → SQLite (local default, Render with a persistent disk)
//   - on Vercel with no DATABASE_URL → SQLite in /tmp. Serverless /tmp is per instance and is wiped,
//     so this demo store RESETS; the UI says so (see `ephemeralStore`).

// Marketplace Postgres add-ons may set DATABASE_URL to a proxy URL and the direct connection in POSTGRES_URL.
const isPg = (u?: string) => /^postgres(ql)?:\/\//.test(u || "");
if (!isPg(process.env.DATABASE_URL) && !/^file:/.test(process.env.DATABASE_URL || "") && isPg(process.env.POSTGRES_URL)) {
  process.env.DATABASE_URL = process.env.POSTGRES_URL;
}

export const ephemeralStore = !!process.env.VERCEL && !process.env.DATABASE_URL;
if (ephemeralStore) process.env.DATABASE_URL = "file:/tmp/anytill-demo.sqlite";

// The SQLite migrations, bundled so a fresh /tmp database can be created at runtime.
const MIGRATIONS = import.meta.glob("../prisma/migrations/*/migration.sql", { query: "?raw", import: "default", eager: true }) as Record<string, string>;

async function createSchema(client: PrismaClient) {
  const exists = await client.$queryRawUnsafe<{ name: string }[]>("SELECT name FROM sqlite_master WHERE type='table' AND name='Merchant'");
  if (exists.length) return;
  for (const file of Object.keys(MIGRATIONS).sort()) {
    const statements = MIGRATIONS[file]
      .split(/;\s*\n/)
      .map((s) => s.replace(/^\s*--.*$/gm, "").trim())
      .filter(Boolean);
    for (const sql of statements) await client.$executeRawUnsafe(sql);
  }
}

function makeClient() {
  const base = new PrismaClient();
  if (!ephemeralStore) return base;
  let ready: Promise<void> | undefined;
  // Every query waits until the /tmp schema exists (created once per instance).
  return base.$extends({
    query: {
      async $allOperations({ args, query }) {
        ready ??= createSchema(base);
        await ready;
        return query(args);
      },
    },
  }) as unknown as PrismaClient;
}

declare global {
  // eslint-disable-next-line no-var
  var prismaGlobal: PrismaClient;
}

if (process.env.NODE_ENV !== "production") {
  if (!global.prismaGlobal) global.prismaGlobal = makeClient();
}

const prisma = global.prismaGlobal ?? makeClient();

export default prisma;
